import { deLocalizeDefault, stringifyPattern } from 'wuchale/url';
import { locales, type Locale } from '../locales/data.js';
// Generated by the wuchale CLI (see `wuchale.config.js` → `url.patterns`).
import { matchUrl } from '../locales/main.url.js';
import { localize } from './url.js';

export { localize, locales };

/** The locale whose URLs are not prefixed (`/about`, not `/en/about`). */
export const sourceLocale: Locale = locales[0];

export function isLocale(value: string | null | undefined): value is Locale {
	return !!value && (locales as readonly string[]).includes(value);
}

/**
 * The locale a URL asks for: `am` for `/am/proverbs/2`, `en` for `/proverbs/2`.
 *
 * This is the single source of truth for the site language — there is no cookie
 * and no query parameter any more, so SSR, client-side navigation, prefetching
 * and a bookmarked link all agree by construction.
 */
export function localeFromPathname(pathname: string): Locale {
	return deLocalizeDefault(pathname, locales)[1] ?? sourceLocale;
}

/**
 * The same page in the other locale: `/am/proverbs/2` → `/proverbs/2`.
 *
 * Goes through the URL manifest rather than just swapping the prefix, so that
 * translating a *path* (e.g. `/about` → `/ስለ` in `en.po`/`am.po`) keeps the
 * toggle pointing at the right page instead of a 404. Unknown paths — a 404,
 * or a route outside `url.patterns` — only swap the prefix.
 *
 * `search` is re-attached verbatim: the query string (`?page=2`, `?search=…`)
 * isn't part of any pattern and belongs to the page, not the language.
 */
export function switchLocaleUrl(pathname: string, target: Locale, search = ''): string {
	const [path, from] = deLocalizeDefault(pathname, locales);
	const { path: matched, params, altPatterns } = matchUrl(path, from);
	const next =
		matched === null
			? localize(path, target)
			: localize(stringifyPattern(altPatterns[target], params), target);
	return next + search;
}
